WITH unpacked AS (SELECT id, status_code, payload_json, context, context['trace'] AS trace, context['version'] AS version, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, CAST((status_code & 1) != 0 AS INT) AS has_fault, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs WHERE status_code <= 435) SELECT CASE WHEN status_code >= 463 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, tier, SORT_ARRAY(COLLECT_SET(tier)) AS tier_list, PERCENTILE_APPROX(status_code, 0.9) AS status_code_p90, GROUPING(CASE WHEN status_code >= 463 THEN 'LARGE' ELSE 'SMALL' END) AS grouping_id FROM unpacked GROUP BY ROLLUP (CASE WHEN status_code >= 463 THEN 'LARGE' ELSE 'SMALL' END, tier) ORDER BY status_code_tier;
